inline int index(const std::string& name)
{
    for (int i = 0; i < nSpecies; ++i)
        if (name == species[i].name) return i;
    return -1;
}

inline const double* rangeCoeffs(const SandiegoSpeciesData& s, double T)
{
    return T < s.Tcommon ? s.lo : s.hi;
}

// San Diego coefficients are evaluated as pure polynomials (no
// clamping), matching Cantera/CEA practice for states outside the
// nominal NASA-7 range (e.g. C3H5 Thigh=3000 K at T=3800 K).
inline double cpR(const double* a, double T)
{
    return a[0] + T * (a[1] + T * (a[2] + T * (a[3] + T * a[4])));
}

inline double hOverR(const double* a, double T)
{
    return T * (a[0] + T * (a[1] / 2.0 + T * (a[2] / 3.0 + T * (a[3] / 4.0 + T * (a[4] / 5.0))))) + a[5];
}

// cp [J/(mol K)] (pure polynomial evaluation).
inline double cpMole(int i, double T)
{
    const SandiegoSpeciesData& s = species[i];
    return Runiv * cpR(rangeCoeffs(s, T), T);
}

// absolute molar enthalpy [J/mol] (pure polynomial evaluation).
inline double hMole(int i, double T)
{
    const SandiegoSpeciesData& s = species[i];
    return Runiv * hOverR(rangeCoeffs(s, T), T);
}

// standard molar entropy [J/(mol K)] (pure polynomial evaluation).
inline double sMole(int i, double T)
{
    const SandiegoSpeciesData& s = species[i];
    const double* a = rangeCoeffs(s, T);
    return Runiv * (a[0] * std::log(T) + T * (a[1] + T * (a[2] / 2.0 + T * (a[3] / 3.0 + T * (a[4] / 4.0)))) + a[6]);
}

